# Define all possible single-digit additions that sum to an odd number under 10
results = []
for a in range(10):
    for b in range(10):
        s = a + b
        if s < 10 and s % 2 == 1:
            results.append((a, b, s))

# Convert each addition to its hex representation and compute decimal equivalents
def hex_and_decimal(a, b):
    combined_hex = f"{a:01X}{b:01X}{b:01X}{a:01X}"
    decimal_value = int(combined_hex, 16)
    digital_root = sum(int(d) for d in str(decimal_value))
    while digital_root >= 10:
        digital_root = sum(int(d) for d in str(digital_root))
    return combined_hex, decimal_value, digital_root

# Collect results
mapped_data = []
for a, b, s in results:
    hex_val, dec_val, droot = hex_and_decimal(a, b)
    mapped_data.append({
        "A": a,
        "B": b,
        "Sum": s,
        "Hex": hex_val,
        "Decimal": dec_val,
        "Digital Root": droot
    })

import pandas as pd
df = pd.DataFrame(mapped_data)

import ace_tools as tools; tools.display_dataframe_to_user(name="Odd Sums Under 10 with Hex and Digital Root", dataframe=df)

