import hashlib
import binascii
import pandas as pd

def hexify(nonce):
    """Convert integer to hex string"""
    return format(nonce, 'x')

def text_to_hex(text):
    """Convert ASCII string to hex string"""
    return binascii.hexlify(text.encode()).decode()

def hex_to_decimal(hex_string):
    """Convert hex string to decimal integer"""
    return int(hex_string, 16)

def decimal_to_ascii(decimal_val):
    """Convert decimal integer to ASCII hex and decode"""
    hex_string = format(decimal_val, 'x')
    # Ensure even-length hex
    if len(hex_string) % 2 != 0:
        hex_string = '0' + hex_string
    try:
        return binascii.unhexlify(hex_string).decode('utf-8', errors='replace')
    except Exception as e:
        return str(e)

def track_recursive_transform(nonce):
    """Track all stages of the recursive transformation"""
    original_hex = hexify(nonce)
    as_text = original_hex
    text_to_hex_str = text_to_hex(as_text)
    hex_to_dec = hex_to_decimal(text_to_hex_str)
    dec_to_text = decimal_to_ascii(hex_to_dec)

    return {
        "nonce": nonce,
        "original_hex": original_hex,
        "text_to_hex": text_to_hex_str,
        "hex_to_decimal": hex_to_dec,
        "decimal_to_text": dec_to_text
